"""OCC report rendering helpers for P0."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from jinja2 import Environment, FileSystemLoader

DISCLAIMER_TEXT = (
    "This validation report is generated by an analytical workbench for model risk "
    "and fair-lending **review support**. It does not constitute legal advice, "
    "a regulatory filing, or a determination of compliance with any applicable law."
)

LIMITATIONS_TEXT = (
    "**Demo limitations:** This validation uses the UCI German Credit dataset "
    "(German domestic credit, circa 1990s). It does not represent US lending "
    "populations. No race/ethnicity fields are available; BISG proxy analysis is "
    "**not performed**. Population drift is **injected covariate shift** for "
    "pedagogical demonstration, not observed production drift. State overlay toggles "
    "(P3) illustrate jurisdictional framing only."
)

_APPENDIX_NOT_APPLICABLE = "Not applicable — adverse_action_translator disabled"
_APPENDIX_C_NOT_RUN = "Not run — drift module disabled"


@dataclass(slots=True)
class ReportArtifacts:
    markdown_path: Path
    report_json_path: Path
    appendix_b_path: Path
    appendix_e_path: Path
    appendix_a_path: Path | None = None
    appendix_d_path: Path | None = None
    appendix_c_path: Path | None = None


def generate_occ_report(
    *,
    artifact_dir: Path,
    run_context: dict[str, Any],
    bias_summary: dict[str, Any],
    audit_summary: dict[str, Any],
    appendix_a_path: Path | None = None,
    appendix_d_path: Path | None = None,
    appendix_c_path: Path | None = None,
    limitations_text: str | None = None,
) -> ReportArtifacts:
    """Render the OCC report + write appendices B and E.

    Appendices A (`translation_methodology_v1.json`), C (`drift_report.json`),
    and D (`fidelity_validation_report.json`) are written earlier by the P1
    adverse-action step and P2 drift step, before their respective
    `adverse_action.methodology_published` / `drift.event` audit events —
    their paths are passed in here only to populate the report appendix
    index and template context, not written again.

    `limitations_text` defaults to the German-Credit-specific `LIMITATIONS_TEXT`
    module constant (byte-identical to pre-P5 behavior) when omitted; datasets
    outside that demo (e.g. P5's synth-fin CRE panel) pass their own accurate
    text via `ValidationRunConfig.limitations_text` instead of inheriting a
    claim about a dataset they don't use.
    """
    resolved_limitations = limitations_text if limitations_text is not None else LIMITATIONS_TEXT
    artifact_dir.mkdir(parents=True, exist_ok=True)
    appendix_b_path = artifact_dir / "bias_battery_summary.json"
    appendix_b_path.write_text(json.dumps(bias_summary, indent=2, sort_keys=True))

    appendix_e_path = artifact_dir / "audit_chain_verification.json"
    appendix_e_path.write_text(json.dumps(audit_summary, indent=2, sort_keys=True))

    template_dir = Path(__file__).resolve().parent / "templates" / "occ_2026_13"
    env = Environment(
        loader=FileSystemLoader(template_dir),
        autoescape=False,
        trim_blocks=True,
        lstrip_blocks=True,
    )
    template = env.get_template("report.md.j2")
    markdown = template.render(
        context=run_context,
        disclaimer=DISCLAIMER_TEXT,
        limitations=resolved_limitations,
    )

    markdown_path = artifact_dir / "validation_report.md"
    markdown_path.write_text(markdown.strip() + "\n")

    def _appendix_ref(path: Path) -> str:
        """Render an appendix reference relative to the artifact directory.

        Absolute paths would leak the generating machine's filesystem layout
        into a published artifact, and are meaningless to anyone reading the
        report elsewhere. Every appendix is written into artifact_dir, so the
        relative form is both portable and sufficient to locate the file.
        """
        try:
            return str(path.resolve().relative_to(artifact_dir.resolve()))
        except ValueError:
            return path.name

    report_json = {
        "run_context": run_context,
        "disclaimer": DISCLAIMER_TEXT,
        "limitations": resolved_limitations,
        "appendices": {
            "A": _appendix_ref(appendix_a_path) if appendix_a_path else _APPENDIX_NOT_APPLICABLE,
            "B": _appendix_ref(appendix_b_path),
            "C": _appendix_ref(appendix_c_path) if appendix_c_path else _APPENDIX_C_NOT_RUN,
            "D": _appendix_ref(appendix_d_path) if appendix_d_path else _APPENDIX_NOT_APPLICABLE,
            "E": _appendix_ref(appendix_e_path),
        },
    }
    report_json_path = artifact_dir / "report.json"
    report_json_path.write_text(json.dumps(report_json, indent=2, sort_keys=True))

    return ReportArtifacts(
        markdown_path=markdown_path,
        report_json_path=report_json_path,
        appendix_b_path=appendix_b_path,
        appendix_e_path=appendix_e_path,
        appendix_a_path=appendix_a_path,
        appendix_d_path=appendix_d_path,
        appendix_c_path=appendix_c_path,
    )
